import { TRUSTED_ORIGINS } from '../constants';
import { BG } from 'bgutils-js';

// Make BG available globally for eval'd code (used by PoToken generation)
(window as any).BG = BG;

window.addEventListener('message', async (event) => {
    if (!TRUSTED_ORIGINS.includes(event.origin)) {
        console.error("Untrusted message received from origin ", event?.origin);
        // Ignore the message from untrusted origins
        return;
    }
    const content = event.data?.content;
    if (content) {
        try {
            const result = await eval(content);
            (event.source as Window).postMessage({ result }, event.origin as any);
        } catch (e: any) {
            (event.source as Window).postMessage({ error: e.message }, event.origin as any);
        }
    }
});